// 克制高级 · 风格样片。标准分镜：标题 → 要点 → 数据 → 人名条 → 收尾。
// 可照搬：STYLE 取值、camera()（贯穿全片的缓推）、mask()（遮罩上升入场）、tracked()（加字距）、hairline 母题、grain()（颗粒）。

const STYLE = {
  color: {
    bg: "#101114", // 带一点暖色相的近黑，不用纯黑
    text: "#ECE9E3",
    muted: "#8A8780",
    hairline: "rgba(236,233,227,0.16)",
    accent: "#FF6A3D", // 唯一强调色，只用在点和短线上
  },
  font: {
    title: '"HarmonyOS Sans SC", "Source Han Sans SC", "Noto Sans SC", "Microsoft YaHei", sans-serif',
    latin: '"Inter", "HarmonyOS Sans", "Segoe UI", sans-serif',
  },
};

const SCENES = { title: [0, 1.85], list: [1.85, 3.85], data: [3.85, 5.65], name: [5.65, 6.95], end: [6.95, 8] };
const COPY = {
  title: "把想法变成画面",
  subtitle: "风格样片 · STYLE SAMPLE",
  list: ["统一的配色", "统一的字体", "统一的节奏"],
  data: { value: 87, unit: "%", label: "一次通过率" },
  name: { name: "痕继痕迹", role: "动效设计师" },
  end: "一个风格，处处一致",
};

const clamp = (v) => Math.max(0, Math.min(1, v));
const expoOut = (v) => (v >= 1 ? 1 : 1 - Math.pow(2, -10 * clamp(v)));
const cubicIn = (v) => clamp(v) ** 3;
const cubicInOut = (v) => { v = clamp(v); return v < 0.5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
const lerp = (a, b, k) => a + (b - a) * k;
const font = (weight, size, family) => `${weight} ${Math.round(size)}px ${family}`;

// 入场 0.8 s expoOut，离场 0.35 s cubicIn；落地后没有新动作，只随 camera() 的缓推走。
function phase(t, [a, b], delay = 0, inDur = 0.8, outDur = 0.35) {
  return { enter: expoOut((t - a - delay) / inDur), leave: cubicIn((t - (b - outDur)) / outDur), on: t >= a && t < b };
}

// 承载运动：整个画面以中心为原点匀速推近，约每秒 1%，从第一帧跑到最后一帧，不起停、不变速。
// 场景之间是细线接力而不是切镜，所以不重置。入场位移叠在它上面，落地后只剩缓推，接点处速度不降到零。
const PUSH = 0.01;
function camera(t, w, h) {
  const s = 1 + PUSH * t;
  return { s, at: (x, y) => [w / 2 + (x - w / 2) * s, h / 2 + (y - h / 2) * s] };
}

// 加字距逐字绘制（拉丁小标签用宽字距，中文标题略收紧）。
function tracked(ctx, text, x, y, tracking, align = "left") {
  const chars = [...text];
  const widths = chars.map((c) => ctx.measureText(c).width);
  const total = widths.reduce((s, v) => s + v, 0) + tracking * (chars.length - 1);
  let cx = align === "center" ? x - total / 2 : x;
  chars.forEach((c, i) => { ctx.fillText(c, cx, y); cx += widths[i] + tracking; });
  return total;
}

// 只用来量字宽（分层时还没有画布）。
let measurer = null;
function measure(text, f, tracking) {
  measurer ??= new OffscreenCanvas(1, 1).getContext("2d");
  measurer.font = f;
  return [...text].reduce((s, c) => s + measurer.measureText(c).width, 0) + tracking * ([...text].length - 1);
}

// 遮罩上升：文字从一条看不见的基线下方升起，离场时继续向上退出。这是本风格唯一的文字入场方式。
// 做成一层：文字只做竖向位移，再随镜头缩放（pose），运行时据此做运动模糊，遮罩边缘保持锐利。
// 遮罩（clip）是画面坐标里的矩形，每帧按当前时刻的镜头换算，跟着画面一起推近。
// text 可以是随时间变化的函数（例如计数），x 可以是函数（跟随前一段文字的宽度）。
function maskText(w, h, now, { text, x, y, size, f, color, tracking = 0, align = "left", scene, delay = 0, inDur = 0.8, outDur = 0.35, maxWidth }) {
  const width = maxWidth ?? measure(typeof text === "function" ? text(scene[1]) : text, f, tracking);
  const left = align === "center" ? -width / 2 : 0, x0 = typeof x === "function" ? 0 : x;
  const cam = camera(now, w, h), [, top] = cam.at(0, y - size * 1.05), [, bottom] = cam.at(0, y + size * 0.3);
  return {
    clip: [0, top, w, bottom],
    bounds: [x0 + left - size * 0.2, y - size * 1.1, (typeof x === "function" ? w : x0) + left + width + size * 0.2, y + size * 0.35],
    pose: (t) => {
      if (t < scene[0] || t >= scene[1]) return null;
      const p = phase(t, scene, delay, inDur, outDur), c = camera(t, w, h), [ox, oy] = c.at(0, 0);
      return { x: ox, y: oy + c.s * ((1 - p.enter) * size * 1.1 - p.leave * size * 1.1), scale: c.s };
    },
    draw: (ctx, t) => {
      ctx.fillStyle = color;
      ctx.font = f;
      tracked(ctx, typeof text === "function" ? text(t) : text, typeof x === "function" ? x(t) : x, y, tracking, align);
    },
  };
}

// 细颗粒：预先生成一张噪点图，每帧换偏移。确定性：只依赖帧序号。
let grainCanvas = null;
function grain(ctx, t, w, h) {
  if (!grainCanvas) {
    grainCanvas = new OffscreenCanvas(1, 1);
    grainCanvas.width = grainCanvas.height = 256;
    const g = grainCanvas.getContext("2d"), img = g.createImageData(256, 256);
    let s = 7;
    for (let i = 0; i < img.data.length; i += 4) {
      s = (s * 16807) % 2147483647;
      const v = (s / 2147483647) * 255;
      img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
      img.data[i + 3] = 255;
    }
    g.putImageData(img, 0, 0);
  }
  const f = Math.floor(t * 24);
  ctx.save();
  ctx.globalAlpha = 0.045;
  ctx.globalCompositeOperation = "overlay";
  ctx.fillStyle = ctx.createPattern(grainCanvas, "repeat");
  ctx.translate((f * 73) % 256, (f * 151) % 256);
  ctx.fillRect(-256, -256, w + 512, h + 512);
  ctx.restore();
}

function background(ctx, w, h) {
  ctx.fillStyle = STYLE.color.bg;
  ctx.fillRect(0, 0, w, h);
  // 左上方一点暖光，四角压暗；都很弱，只为让底色不死板。
  // 渐变两端用同一 RGB 只改透明度：Canvas 按非预乘颜色插值，异色渐隐会出现一圈灰。
  const glow = ctx.createRadialGradient(w * 0.4, h * 0.42, 0, w * 0.4, h * 0.42, w * 0.5);
  glow.addColorStop(0, "rgba(255,244,228,0.05)");
  glow.addColorStop(1, "rgba(255,244,228,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, w, h);
  const vignette = ctx.createRadialGradient(w * 0.5, h * 0.5, h * 0.45, w * 0.5, h * 0.5, w * 0.72);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(1, "rgba(0,0,0,0.45)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, w, h);
}

// 母题：一条贯穿全片的细线。每个场景只改变它的位置和长度，用 cubicInOut 换位，从不消失。
function hairlineAt(t, w, h) {
  const keys = [
    [0.0, { x: w * 0.12, y: h * 0.6, len: 0 }],
    [0.35, { x: w * 0.12, y: h * 0.6, len: w * 0.42 }],
    [1.85, { x: w * 0.12, y: h * 0.6, len: w * 0.42 }],
    [2.25, { x: w * 0.12, y: h * 0.255, len: w * 0.76 }],
    [3.85, { x: w * 0.12, y: h * 0.255, len: w * 0.76 }],
    [4.25, { x: w * 0.12, y: h * 0.7, len: w * 0.76 }],
    [5.65, { x: w * 0.12, y: h * 0.7, len: w * 0.76 }],
    [6.05, { x: w * 0.12, y: h * 0.835, len: w * 0.2 }],
    [6.95, { x: w * 0.12, y: h * 0.835, len: w * 0.2 }],
    [7.35, { x: w * 0.44, y: h * 0.6, len: w * 0.12 }],
  ];
  let i = 0;
  while (i < keys.length - 1 && t >= keys[i + 1][0]) i++;
  const [ta, a] = keys[i], [tb, b] = keys[Math.min(i + 1, keys.length - 1)];
  const k = tb > ta ? cubicInOut((t - ta) / (tb - ta)) : 1;
  return { x: lerp(a.x, b.x, k), y: lerp(a.y, b.y, k), len: lerp(a.len, b.len, k) };
}

function layers(_params, w, h, _assets, info) {
  const u = h / 720, x = w * 0.12, C = STYLE.color, F = STYLE.font, out = [];
  const rise = (opts) => maskText(w, h, info?.time ?? 0, opts);
  // 底：近黑暖底、暖光与压角。像镜头的暗角一样固定在画面上，不随缓推缩放。
  out.push({ draw: (ctx) => background(ctx, w, h) });

  // 标题卡：标签 → 大标题 → 副标题，依次从遮罩里升起。
  const title = SCENES.title;
  out.push(rise({ text: "STYLE SAMPLE — 01", x, y: h * 0.36, size: 12 * u, f: font(500, 12 * u, F.latin), color: C.muted, tracking: 3.6 * u, scene: title, delay: 0.1 }));
  out.push(rise({ text: COPY.title, x: x - 3 * u, y: h * 0.53, size: 78 * u, f: font(300, 78 * u, F.title), color: C.text, tracking: -1.5 * u, scene: title, delay: 0.18 }));
  out.push(rise({ text: COPY.subtitle, x, y: h * 0.68, size: 17 * u, f: font(400, 17 * u, F.title), color: C.muted, tracking: 1.5 * u, scene: title, delay: 0.3 }));

  // 要点：编号与条目一起升起，行间细线向右展开。
  const list = SCENES.list, top = h * 0.4, gap = 104 * u;
  COPY.list.forEach((item, i) => {
    const y = top + i * gap, delay = 0.25 + i * 0.08;
    out.push(rise({ text: `0${i + 1}`, x, y: y - 26 * u, size: 13 * u, f: font(400, 13 * u, F.latin), color: C.muted, tracking: 2 * u, scene: list, delay }));
    out.push(rise({ text: item, x: x + 80 * u, y, size: 46 * u, f: font(300, 46 * u, F.title), color: C.text, tracking: -0.5 * u, scene: list, delay }));
    if (i < COPY.list.length - 1) out.push(hairlineLayer(w, h, u, (t) => {
      if (t < list[0] || t >= list[1]) return 0;
      return w * 0.64 * expoOut((t - list[0] - 0.35 - i * 0.08) / 0.9) * (1 - cubicIn((t - (list[1] - 0.35)) / 0.35));
    }, () => ({ x: x + 80 * u, y: y + 34 * u }), C.hairline));
  });

  // 数据：巨大的细数字计数升起，单位跟在数字后面；说明靠右。
  const data = SCENES.data, numFont = font(200, 220 * u, F.latin);
  const count = (t) => COPY.data.value * expoOut((t - data[0] - 0.2) / 1.3);
  const numText = (t) => String(Math.round(count(t)));
  const numWidth = (t) => measure(numText(t), numFont, -8 * u);
  out.push(rise({ text: numText, x: x - 10 * u, y: h * 0.6, size: 220 * u, f: numFont, color: C.text, tracking: -8 * u, scene: data, delay: 0.15, maxWidth: measure("88", numFont, -8 * u) }));
  out.push(rise({ text: COPY.data.unit, x: (t) => x - 10 * u + numWidth(t) + 16 * u, y: h * 0.6 - 120 * u, size: 48 * u, f: font(300, 48 * u, F.latin), color: C.text, scene: data, delay: 0.15, maxWidth: 40 * u }));
  out.push(rise({ text: COPY.data.label, x: w * 0.88 - 86 * u, y: h * 0.6, size: 17 * u, f: font(400, 17 * u, F.title), color: C.muted, tracking: 1.5 * u, scene: data, delay: 0.3 }));

  // 人名条：名字与职位同一行升起。
  const name = SCENES.name, nameFont = font(500, 28 * u, F.title), nameW = measure(COPY.name.name, nameFont, 4 * u);
  out.push(rise({ text: COPY.name.name, x, y: h * 0.8, size: 28 * u, f: nameFont, color: C.text, tracking: 4 * u, scene: name, delay: 0.25, inDur: 0.7 }));
  out.push(rise({ text: COPY.name.role, x: x + nameW + 28 * u, y: h * 0.8, size: 16 * u, f: font(400, 16 * u, F.title), color: C.muted, tracking: 2 * u, scene: name, delay: 0.33, inDur: 0.7 }));

  // 收尾：一句话居中升起。
  out.push(rise({ text: COPY.end, x: w / 2, y: h * 0.53, size: 40 * u, f: font(300, 40 * u, F.title), color: C.text, tracking: 6 * u, align: "center", scene: [SCENES.end[0], 99], delay: 0.3, inDur: 0.9 }));

  // 母题细线：底线随场景换位、伸缩；数据场景里叠一段亮色进度；强调色圆点停在线端（或进度端）。
  const progress = (t) => (t >= data[0] && t < data[1] ? count(t) / 100 : null);
  out.push(hairlineLayer(w, h, u, (t) => hairlineAt(t, w, h).len, (t) => hairlineAt(t, w, h), C.hairline));
  out.push(hairlineLayer(w, h, u, (t) => { const p = progress(t); return p == null ? 0 : hairlineAt(t, w, h).len * p; }, (t) => hairlineAt(t, w, h), C.text));
  out.push({
    bounds: [-3.5 * u, -3.5 * u, 3.5 * u, 3.5 * u],
    pose: (t) => {
      const l = hairlineAt(t, w, h), p = progress(t), c = camera(t, w, h);
      if (l.len <= 2) return null;
      const [px, py] = c.at(l.x + (p == null ? l.len : l.len * p), l.y + 0.5 * u);
      return { x: px, y: py, scale: c.s };
    },
    draw: (ctx) => {
      ctx.fillStyle = C.accent;
      ctx.beginPath();
      ctx.arc(0, 0, 3 * u, 0, Math.PI * 2);
      ctx.fill();
    },
  });

  // 最上面一层细颗粒。
  out.push({ draw: (ctx, t) => grain(ctx, t, w, h) });
  return out;
}

// 一段可伸缩的细线：内容是 100 像素长的线，按长度横向缩放；长度为 0 时不画。
function hairlineLayer(w, h, u, lengthAt, originAt, color) {
  return {
    bounds: [0, 0, 100, Math.max(1, u)],
    pose: (t) => {
      const len = lengthAt(t);
      if (len < 0.5) return null;
      const o = originAt(t), c = camera(t, w, h), [x, y] = c.at(o.x, o.y);
      return { x, y, scaleX: (len / 100) * c.s, scaleY: c.s };
    },
    draw: (ctx) => {
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, 100, Math.max(1, u));
    },
  };
}

export default {
  name: "克制高级 · 样片", kind: "generator", mode: "dynamic",
  nameEnglish: "Restrained Premium · Sample",
  params: [],
  // 从容的动作配 180° 快门：快速升起时有一点拖影，落地后只剩极慢的缓推，看起来是清晰的。
  motionBlur: { shutter: 180 },
  layers,
};
